const body = $input.first().json.body || $input.first().json;
const query = (body.query || body.q || body.message || '').toString().trim();
const limit = Number(body.limit || 5);
if (!query) {
  return [{ json: { error: true, reply: 'query missing' } }];
}
return [{ json: { query, limit } }];

const prev = $('Parse query').item.json;
const emb = $input.first().json.embedding;
if (!emb) {
  return [{ json: { error: true, reply: 'embedding missing', query: prev.query } }];
}
// Load your PRIVATE exclude list at runtime (env / file), not hard-coded secrets.
// Example motifs from zones.example.json only:
const excludes = ['PRIVATE_LIFE_FOLDER','PRIVATE_CHAT_EXPORTS','RAW_IDEA_ATOMS','PERSONAL_JOURNAL','PEOPLE_ROSTER','SENSITIVE_INTAKE'];
const must_not = excludes.map((p) => ({ key: 'sourceFile', match: { text: p } }));
const fetchLimit = Math.max(Number(prev.limit || 5) * 4, 20);
return [{ json: { query: prev.query, limit: prev.limit, fetchLimit, embedding: emb, zoneFilter: { must_not }, excludes } }];

const prev = $('Parse query').item.json;
const pack = $('Pack vector').item.json;
const raw = $input.first().json;
const excludes = pack.excludes || [];
function excluded(path) {
  if (!path) return true;
  const n = String(path);
  return excludes.some((p) => n.includes(p));
}
let hits = (raw.result || []).filter((h) => !excluded(h.payload && h.payload.sourceFile)).map((h) => ({
  score: h.score,
  file: h.payload && h.payload.source_filename,
  path: h.payload && h.payload.sourceFile,
  excerpt: h.payload && h.payload.text ? String(h.payload.text).slice(0, 280) : null
}));
hits = hits.slice(0, Number(prev.limit || 5));
return [{ json: { ok: true, agent: 'vault-rag', query: prev.query, zoneFilter: true, hits } }];
